P1T-CD01:
NUMBER value.
INPUT(value).
IF (value < 0) {
    DISPLAYNL("NEGATIVE").
} ELSEIF (value == 0) {
    DISPLAYNL("ZERO").
} ELSE {
    DISPLAYNL("POSITIVE").
}

P1T-CD02:
NUMBER score.
INPUT(score).
IF (score >= 90) {
    DISPLAYNL("A").
} ELSEIF (score >= 75) {
    DISPLAYNL("B").
} ELSEIF (score >= 60) {
    DISPLAYNL("C").
} ELSE {
    DISPLAYNL("F").
}

P1T-CD03:
IMPORT strings.
SENTENCE line.
INPUT(line).
SENTENCE[] p = strings.SPLIT(line, "|").
NUMBER a = strings.TO_NUMBER(p[0]).
NUMBER b = strings.TO_NUMBER(p[1]).
NUMBER c = strings.TO_NUMBER(p[2]).
IF (a > 0 AND b > 0 AND c > 0 AND a + b > c AND a + c > b AND b + c > a) {
    DISPLAYNL("VALID").
} ELSE {
    DISPLAYNL("INVALID").
}

P1T-CD04:
NUMBER year.
INPUT(year).
LOGIC leap = year % 400 == 0 OR (year % 4 == 0 AND year % 100 != 0).
IF (leap) {
    DISPLAYNL("LEAP").
} ELSE {
    DISPLAYNL("COMMON").
}

P1T-CD05:
IMPORT strings.
SENTENCE line.
INPUT(line).
SENTENCE[] p = strings.SPLIT(line, "|").
NUMBER a = strings.TO_NUMBER(p[0]).
NUMBER b = strings.TO_NUMBER(p[1]).
NUMBER c = strings.TO_NUMBER(p[2]).
IF ((a >= b AND a <= c) OR (a >= c AND a <= b)) {
    DISPLAYNL(a).
} ELSEIF ((b >= a AND b <= c) OR (b >= c AND b <= a)) {
    DISPLAYNL(b).
} ELSE {
    DISPLAYNL(c).
}

P1T-CD06:
NUMBER n.
INPUT(n).
IF (n <= 0) {
    DISPLAYNL("NONPOSITIVE").
} ELSE {
    IF (n % 2 == 0) {
        DISPLAYNL("POSITIVE EVEN").
    } ELSE {
        DISPLAYNL("POSITIVE ODD").
    }
}

P1T-CD07:
NUMBER temperature.
INPUT(temperature).
IF (temperature < 10) {
    DISPLAYNL("COLD").
} ELSEIF (temperature <= 25) {
    DISPLAYNL("MILD").
} ELSE {
    DISPLAYNL("HOT").
}

P1T-CD08:
IMPORT strings.
SENTENCE coordinates.
INPUT(coordinates).
SENTENCE[] p = strings.SPLIT(coordinates, "|").
NUMBER x = strings.TO_NUMBER(p[0]).
NUMBER y = strings.TO_NUMBER(p[1]).
IF (x == 0 OR y == 0) {
    DISPLAYNL("AXIS").
} ELSEIF (x > 0 AND y > 0) {
    DISPLAYNL("Q1").
} ELSEIF (x < 0 AND y < 0) {
    DISPLAYNL("Q3").
} ELSE {
    DISPLAYNL("MIXED").
}

P1T-LP03:
IMPORT strings.
SENTENCE line.
INPUT(line).
SENTENCE[] p = strings.SPLIT(line, "|").
NUMBER limit = strings.TO_NUMBER(p[0]).
NUMBER divisor = strings.TO_NUMBER(p[1]).
NUMBER count = 0.
LOOP (NUMBER candidate = 1 TILL candidate <= limit, candidate++) {
    IF (candidate % divisor == 0) {
        count++.
    }
}
DISPLAYNL(count).

P1T-LP04:
NUMBER n.
INPUT(n).
LOOP (NUMBER multiplier = 1 TILL multiplier <= 5, multiplier++) {
    DISPLAYNL(n * multiplier).
}

P1T-LP06:
NUMBER n.
INPUT(n).
LOOP (NUMBER evenValue = 0 TILL evenValue <= n, evenValue += 2) {
    DISPLAYNL(evenValue).
}

P1T-LP07:
IMPORT strings.
SENTENCE dimensions.
INPUT(dimensions).
SENTENCE[] p = strings.SPLIT(dimensions, "|").
NUMBER rows = strings.TO_NUMBER(p[0]).
NUMBER columns = strings.TO_NUMBER(p[1]).
LOOP (NUMBER row = 0 TILL row < rows, row++) {
    LOOP (NUMBER column = 0 TILL column < columns, column++) {
        DISPLAY("*").
    }
    DISPLAYNL("").
}

P1T-LP08:
NUMBER n.
INPUT(n).
NUMBER total = 0.
LOOP (NUMBER i = 1 TILL i <= n, i++) {
    IF (i % 2 == 0) {
        total -= i.
    } ELSE {
        total += i.
    }
}
DISPLAYNL(total).

P1T-FN01:
FUNCTION cube(NUMBER x) {
    RETURN x * x * x.
} RETURNS NUMBER.
NUMBER inputValue.
INPUT(inputValue).
DISPLAYNL(cube(inputValue)).

P1T-FN02:
IMPORT strings.
FUNCTION clampValue(NUMBER value, NUMBER low, NUMBER high) {
    IF (value < low) {
        RETURN low.
    }
    IF (value > high) {
        RETURN high.
    }
    RETURN value.
} RETURNS NUMBER.
SENTENCE line.
INPUT(line).
SENTENCE[] p = strings.SPLIT(line, "|").
DISPLAYNL(clampValue(strings.TO_NUMBER(p[0]), strings.TO_NUMBER(p[1]), strings.TO_NUMBER(p[2]))).

P1T-FN03:
IMPORT strings.
FUNCTION isMultiple(NUMBER value, NUMBER divisor) {
    RETURN value % divisor == 0.
} RETURNS LOGIC.
SENTENCE line.
INPUT(line).
SENTENCE[] p = strings.SPLIT(line, "|").
LOGIC answer = isMultiple(strings.TO_NUMBER(p[0]), strings.TO_NUMBER(p[1])).
IF (answer) {
    DISPLAYNL("YES").
} ELSE {
    DISPLAYNL("NO").
}

P1T-FN04:
IMPORT strings.
FUNCTION absoluteDifference(NUMBER a, NUMBER b) {
    IF (a >= b) {
        RETURN a - b.
    }
    RETURN b - a.
} RETURNS NUMBER.
SENTENCE pairText.
INPUT(pairText).
SENTENCE[] p = strings.SPLIT(pairText, "|").
NUMBER left = strings.TO_NUMBER(p[0]).
NUMBER right = strings.TO_NUMBER(p[1]).
DISPLAYNL(absoluteDifference(left, right)).

P1T-FN05:
FUNCTION triangleSum(NUMBER n) {
    NUMBER total = 0.
    LOOP (NUMBER i = 1 TILL i <= n, i++) {
        total += i.
    }
    RETURN total.
} RETURNS NUMBER.
NUMBER n.
INPUT(n).
DISPLAYNL(triangleSum(n)).

P1T-FN06:
IMPORT strings.
FUNCTION minTwo(NUMBER a, NUMBER b) {
    IF (a < b) {
        RETURN a.
    }
    RETURN b.
} RETURNS NUMBER.
FUNCTION minThree(NUMBER a, NUMBER b, NUMBER c) {
    RETURN minTwo(minTwo(a, b), c).
} RETURNS NUMBER.
SENTENCE line.
INPUT(line).
SENTENCE[] p = strings.SPLIT(line, "|").
DISPLAYNL(minThree(strings.TO_NUMBER(p[0]), strings.TO_NUMBER(p[1]), strings.TO_NUMBER(p[2]))).

P1T-FN07:
FUNCTION parityLabel(NUMBER n) {
    IF (n % 2 == 0) {
        RETURN "EVEN".
    }
    RETURN "ODD".
} RETURNS SENTENCE.
NUMBER value.
INPUT(value).
SENTENCE label = parityLabel(value).
DISPLAYNL(label).

P1T-AR03:
IMPORT strings.
SENTENCE line.
INPUT(line).
SENTENCE[] p = strings.SPLIT(line, "|").
NUMBER[] values = [strings.TO_NUMBER(p[0]), strings.TO_NUMBER(p[1]), strings.TO_NUMBER(p[2]), strings.TO_NUMBER(p[3]), strings.TO_NUMBER(p[4])].
NUMBER positiveCount = 0.
LOOP (NUMBER index = 0 TILL index < 5, index++) {
    IF (values[index] > 0) {
        positiveCount++.
    }
}
DISPLAYNL(positiveCount).

P1T-AR04:
IMPORT strings.
SENTENCE line.
INPUT(line).
SENTENCE[] p = strings.SPLIT(line, "|").
NUMBER target = strings.TO_NUMBER(p[0]).
NUMBER[] values = [strings.TO_NUMBER(p[1]), strings.TO_NUMBER(p[2]), strings.TO_NUMBER(p[3]), strings.TO_NUMBER(p[4])].
NUMBER matches = 0.
LOOP (NUMBER i = 0 TILL i < 4, i++) {
    IF (values[i] == target) {
        matches++.
    }
}
DISPLAYNL(matches).

P1T-AR07:
IMPORT strings.
SENTENCE line.
INPUT(line).
SENTENCE[] p = strings.SPLIT(line, "|").
NUMBER[] values = [strings.TO_NUMBER(p[0]), strings.TO_NUMBER(p[1]), strings.TO_NUMBER(p[2]), strings.TO_NUMBER(p[3])].
NUMBER minimum = values[0].
NUMBER maximum = values[0].
LOOP (NUMBER i = 1 TILL i < 4, i++) {
    IF (values[i] < minimum) {
        minimum = values[i].
    }
    IF (values[i] > maximum) {
        maximum = values[i].
    }
}
DISPLAYNL(maximum - minimum).

P1T-ST03:
IMPORT strings.
SENTENCE line.
INPUT(line).
SENTENCE[] p = strings.SPLIT(line, "|").
LOGIC starts = strings.STARTSWITH(p[1], p[0]).
LOGIC ends = strings.ENDSWITH(p[1], p[2]).
IF (starts AND ends) {
    DISPLAYNL("BOTH").
} ELSE {
    DISPLAYNL("NO").
}

P1T-ST07:
IMPORT strings.
SENTENCE line.
INPUT(line).
SENTENCE[] p = strings.SPLIT(line, "|").
IF (strings.CONTAINS(p[0], p[1])) {
    DISPLAYNL("FOUND").
} ELSE {
    DISPLAYNL("MISSING").
}

P1T-CP01:
NUMBER n.
INPUT(n).
LOGIC prime = n > 1.
LOOP (NUMBER divisor = 2 TILL divisor * divisor <= n, divisor++) {
    IF (n % divisor == 0) {
        prime = FALSE.
    }
}
IF (prime) {
    DISPLAYNL("PRIME").
} ELSE {
    DISPLAYNL("COMPOSITE").
}

P1T-CP03:
IMPORT strings.
SENTENCE text.
INPUT(text).
SENTENCE lowered = strings.LOWER(text).
SENTENCE reversed = strings.REVERSE(lowered).
IF (strings.EQUALS(lowered, reversed)) {
    DISPLAYNL("PALINDROME").
} ELSE {
    DISPLAYNL("DIFFERENT").
}

P1T-CP05:
NUMBER n.
INPUT(n).
NUMBER divisorSum = 0.
LOOP (NUMBER d = 1 TILL d < n, d++) {
    IF (n % d == 0) {
        divisorSum += d.
    }
}
IF (divisorSum == n) {
    DISPLAYNL("PERFECT").
} ELSEIF (divisorSum > n) {
    DISPLAYNL("ABUNDANT").
} ELSE {
    DISPLAYNL("DEFICIENT").
}

P1T-CP06:
IMPORT math.
NUMBER n.
INPUT(n).
LOGIC power = TRUE.
LOOP (n > 1) {
    IF (n % 2 != 0) {
        power = FALSE.
    }
    n = math.FLOOR(n / 2).
}
IF (power) {
    DISPLAYNL("POWER OF TWO").
} ELSE {
    DISPLAYNL("OTHER").
}

P1T-CP07:
IMPORT strings.
SENTENCE line.
INPUT(line).
SENTENCE[] p = strings.SPLIT(line, "|").
NUMBER base = strings.TO_NUMBER(p[0]).
NUMBER exponent = strings.TO_NUMBER(p[1]).
NUMBER result = 1.
LOOP (NUMBER i = 0 TILL i < exponent, i++) {
    result *= base.
}
IF (result % 2 == 0) {
    DISPLAYNL("EVEN").
} ELSE {
    DISPLAYNL("ODD").
}

P1T-CP08:
NUMBER n.
INPUT(n).
NUMBER count = 0.
LOOP (NUMBER i = 1 TILL i <= n, i++) {
    LOGIC byTwo = i % 2 == 0.
    LOGIC byFive = i % 5 == 0.
    IF ((byTwo OR byFive) AND NOT (byTwo AND byFive)) {
        count++.
    }
}
DISPLAYNL(count).
